 "content": "def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 5]
    if len(markers) != 2:
        raise ValueError("expected two marker cells")

    # The marker surrounded by the colored pattern is its origin; the lone 5
    # marks where to copy that pattern.
    def nearby_count(marker):
        r0, c0 = marker
        return sum(
            1 for r, row in enumerate(grid) for c, value in enumerate(row)
            if value != 0 and value != 5 and max(abs(r-r0), abs(c-c0)) <= 2
        )

    source = max(markers, key=nearby_count)
    target = markers[1] if source == markers[0] else markers[0]
    dr, dc = target[0] - source[0], target[1] - source[1]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0 and value != 5:
                rr, cc = r + dr, c + dc
                if 0 <= rr < len(out) and 0 <= cc < len(out[0]):
                    out[rr][cc] = value
    out[target[0]][target[1]] = 0
    return out
